// delimiter-parser.ts
export type Token =
  | { kind: "word"; value: string; offset: number }
  | { kind: "quoted"; value: string; offset: number }
  | { kind: "separator"; value: "," | ";"; offset: number };

export class ParseFailure extends Error {
  constructor(
    message: string,
    readonly offset: number,
  ) {
    super(message);
    this.name = "ParseFailure";
  }
}

export function tokenizeList(source: string): Token[] {
  const tokens: Token[] = [];
  let cursor = 0;

  while (cursor < source.length) {
    const char = source[cursor];
    if (/\s/.test(char)) {
      cursor += 1;
      continue;
    }
    if (char === "," || char === ";") {
      tokens.push({ kind: "separator", value: char, offset: cursor });
      cursor += 1;
      continue;
    }
    if (char === """) {
      const start = cursor++;
      let value = "";
      let closed = false;
      while (cursor < source.length) {
        const next = source[cursor++];
        if (next === """) {
          if (source[cursor] === """) {
            value += """;
            cursor += 1;
          } else {
            closed = true;
            break;
          }
        } else {
          value += next;
        }
      }
      if (!closed) throw new ParseFailure("unterminated quoted value", start);
      tokens.push({ kind: "quoted", value, offset: start });
      continue;
    }

    const start = cursor;
    while (cursor < source.length && !/[\s,;]/.test(source[cursor])) cursor += 1;
    tokens.push({ kind: "word", value: source.slice(start, cursor), offset: start });
  }
  return tokens;
}

export function parseGroups(source: string): string[][] {
  const groups: string[][] = [[]];
  let expectsValue = true;
  for (const token of tokenizeList(source)) {
    if (token.kind === "separator") {
      if (expectsValue) throw new ParseFailure("missing value before separator", token.offset);
      if (token.value === ";") groups.push([]);
      expectsValue = true;
      continue;
    }
    if (!expectsValue) throw new ParseFailure("missing separator", token.offset);
    groups.at(-1)?.push(token.value);
    expectsValue = false;
  }
  if (expectsValue && source.trim() !== "") {
    throw new ParseFailure("list cannot end with a separator", source.length - 1);
  }
  return groups;
}

// reservation-handler.ts
import { createHash } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";
import { inventory } from "./inventory-store.js";

type ReservationBody = {
  facilityId: string;
  sku: string;
  quantity: number;
  expiresAt?: string;
};

async function readJson(request: IncomingMessage, limit = 32_768): Promise<unknown> {
  const chunks: Buffer[] = [];
  let length = 0;
  for await (const chunk of request) {
    const bytes = Buffer.from(chunk);
    length += bytes.length;
    if (length > limit) throw Object.assign(new Error("body too large"), { status: 413 });
    chunks.push(bytes);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString("utf8"));
  } catch (cause) {
    throw Object.assign(new Error("request body is not valid JSON", { cause }), { status: 400 });
  }
}

function validateBody(value: unknown): ReservationBody {
  if (!value || typeof value !== "object") {
    throw Object.assign(new Error("expected an object"), { status: 400 });
  }
  const body = value as Record<string, unknown>;
  if (typeof body.facilityId !== "string" || body.facilityId.length < 2) {
    throw Object.assign(new Error("facilityId is required"), { status: 400 });
  }
  if (typeof body.sku !== "string" || !/^[A-Z0-9-]+$/.test(body.sku)) {
    throw Object.assign(new Error("sku has an invalid format"), { status: 400 });
  }
  if (!Number.isSafeInteger(body.quantity) || Number(body.quantity) <= 0) {
    throw Object.assign(new Error("quantity must be a positive integer"), { status: 400 });
  }
  return body as ReservationBody;
}

export async function reserve(request: IncomingMessage, response: ServerResponse) {
  const requestId = request.headers["x-request-id"]?.toString() ?? crypto.randomUUID();
  try {
    const key = request.headers["idempotency-key"]?.toString();
    if (!key) throw Object.assign(new Error("idempotency-key is required"), { status: 400 });
    const body = validateBody(await readJson(request));
    const fingerprint = createHash("sha256").update(JSON.stringify(body)).digest("hex");
    const result = await inventory.reserve({ key, fingerprint, ...body });
    response.writeHead(result.created ? 201 : 200, {
      "content-type": "application/json",
      "x-request-id": requestId,
    });
    response.end(JSON.stringify(result.reservation));
  } catch (error) {
    const status = Number((error as { status?: number }).status) || 500;
    response.writeHead(status, { "content-type": "application/json", "x-request-id": requestId });
    response.end(JSON.stringify({
      error: status === 500 ? "internal_error" : "invalid_request",
      message: error instanceof Error ? error.message : "unexpected failure",
    }));
  }
}

