// bin/tally.mjs
import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import process from "node:process";

function parseArgs(argv) {
  const options = { input: null, output: null, group: "category", pretty: false };
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === "--input") options.input = argv[++index];
    else if (argument === "--output") options.output = argv[++index];
    else if (argument === "--group") options.group = argv[++index];
    else if (argument === "--pretty") options.pretty = true;
    else if (argument === "--help") options.help = true;
    else throw new Error("unknown option: " + argument);
  }
  return options;
}

function summarize(rows, groupName) {
  const totals = new Map();
  for (const row of rows) {
    const group = String(row[groupName] ?? "unassigned");
    const amount = Number(row.amount);
    if (!Number.isFinite(amount)) throw new Error("invalid amount in row " + row.id);
    const current = totals.get(group) ?? { count: 0, amount: 0 };
    current.count += 1;
    current.amount += amount;
    totals.set(group, current);
  }
  return [...totals]
    .map(([group, value]) => ({ group, ...value }))
    .sort((left, right) => right.amount - left.amount || left.group.localeCompare(right.group));
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  if (options.help || !options.input) {
    console.error("usage: tally --input records.json [--output totals.json] [--group category]");
    process.exitCode = options.help ? 0 : 2;
    return;
  }
  const inputPath = resolve(options.input);
  const rows = JSON.parse(await readFile(inputPath, "utf8"));
  if (!Array.isArray(rows)) throw new Error("input must contain a JSON array");
  const report = {
    source: inputPath,
    groupedBy: options.group,
    rows: rows.length,
    totals: summarize(rows, options.group),
  };
  const serialized = JSON.stringify(report, null, options.pretty ? 2 : 0) + "
";
  if (options.output) await writeFile(resolve(options.output), serialized, { flag: "wx" });
  else process.stdout.write(serialized);
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});

# reconcile.py
from __future__ import annotations

import asyncio
from collections.abc import AsyncIterator, Callable
from dataclasses import dataclass
from decimal import Decimal
from typing import Protocol


@dataclass(frozen=True)
class Entry:
    account_id: str
    reference: str
    amount: Decimal
    currency: str


class Ledger(Protocol):
    async def entries(self, account_id: str) -> AsyncIterator[Entry]: ...
    async def mark_balanced(self, account_id: str, references: list[str]) -> None: ...


@dataclass
class Reconciliation:
    account_id: str
    debit_total: Decimal
    credit_total: Decimal
    unmatched: list[Entry]

    @property
    def balanced(self) -> bool:
        return self.debit_total + self.credit_total == Decimal("0") and not self.unmatched


async def reconcile_account(
    ledger: Ledger,
    account_id: str,
    *,
    report: Callable[[str], None] = lambda message: None,
) -> Reconciliation:
    by_reference: dict[str, list[Entry]] = {}
    debit_total = Decimal("0")
    credit_total = Decimal("0")

    async for entry in ledger.entries(account_id):
        if entry.amount < 0:
            debit_total += entry.amount
        else:
            credit_total += entry.amount
        by_reference.setdefault(entry.reference, []).append(entry)

    unmatched: list[Entry] = []
    matched_references: list[str] = []
    for reference, entries in sorted(by_reference.items()):
        currencies = {entry.currency for entry in entries}
        total = sum((entry.amount for entry in entries), start=Decimal("0"))
        if len(currencies) == 1 and total == 0:
            matched_references.append(reference)
        else:
            unmatched.extend(entries)
            report(f"{account_id}: reference {reference} remains open")

    result = Reconciliation(account_id, debit_total, credit_total, unmatched)
    if result.balanced:
        await ledger.mark_balanced(account_id, matched_references)
    return result


async def reconcile_many(ledger: Ledger, account_ids: list[str], concurrency: int = 8):
    semaphore = asyncio.Semaphore(concurrency)

    async def guarded(account_id: str):
        async with semaphore:
            return await reconcile_account(ledger, account_id)

    tasks = [asyncio.create_task(guarded(account_id)) for account_id in account_ids]
    return await asyncio.gather(*tasks)

// delimiter-parser.test.ts
import { describe, expect, it } from "vitest";
import { ParseFailure, parseGroups, tokenizeList } from "./delimiter-parser";

describe("tokenizeList", () => {
  it("preserves offsets and quoted separators", () => {
    expect(tokenizeList('alpha, "beta,gamma"; delta')).toEqual([
      { kind: "word", value: "alpha", offset: 0 },
      { kind: "separator", value: ",", offset: 5 },
      { kind: "quoted", value: "beta,gamma", offset: 7 },
      { kind: "separator", value: ";", offset: 19 },
      { kind: "word", value: "delta", offset: 21 },
    ]);
  });

  it("accepts doubled quotes inside a quoted value", () => {
    expect(parseGroups('"a ""small"" thing",next')).toEqual([["a "small" thing", "next"]]);
  });

  it.each([
    [",alpha", 0, "missing value before separator"],
    ["alpha,", 5, "list cannot end with a separator"],
    ["alpha beta", 6, "missing separator"],
    ['"never closed', 0, "unterminated quoted value"],
  ])("rejects %s", (source, offset, message) => {
    try {
      parseGroups(source);
      expect.fail("expected parse failure");
    } catch (error) {
      expect(error).toBeInstanceOf(ParseFailure);
      expect(error).toMatchObject({ message, offset });
    }
  });
});

