describe("reserve", () => {
  it("returns the first reservation again for an identical key", async () => {
    const first = await request(app)
      .post("/reservations")
      .set("idempotency-key", "order-88")
      .send({ facilityId: "east", sku: "TEA-1", quantity: 3 })
      .expect(201);
    const replay = await request(app)
      .post("/reservations")
      .set("idempotency-key", "order-88")
      .send({ facilityId: "east", sku: "TEA-1", quantity: 3 })
      .expect(200);
    expect(replay.body).toEqual(first.body);
  });

  it("rejects a key reused for a different quantity", async () => {
    await seedReservation("order-91", { facilityId: "west", sku: "MUG-2", quantity: 1 });
    const response = await request(app)
      .post("/reservations")
      .set("idempotency-key", "order-91")
      .send({ facilityId: "west", sku: "MUG-2", quantity: 2 })
      .expect(409);
    expect(response.body.error).toBe("idempotency_conflict");
  });
});

