{
  "dashboard": {
    "title": "Fulfillment overview",
    "description": "Order admission, picking, packing, and carrier handoff",
    "time_zone": "browser",
    "refresh": "30s",
    "variables": [
      {
        "name": "environment",
        "label": "Environment",
        "type": "custom",
        "values": ["production", "staging"],
        "default": "production"
      },
      {
        "name": "facility",
        "label": "Facility",
        "type": "query",
        "query": "label_values(fulfillment_orders_total, facility)",
        "include_all": true
      }
    ],
    "rows": [
      {
        "title": "Customer impact",
        "collapsed": false,
        "panels": [
          {
            "id": 1,
            "title": "Orders admitted",
            "kind": "stat",
            "query": "sum(rate(fulfillment_orders_total{environment='$environment',facility=~'$facility'}[5m]))",
            "unit": "orders/s",
            "thresholds": [
              { "color": "green", "value": null },
              { "color": "orange", "value": 40 },
              { "color": "red", "value": 70 }
            ]
          },
          {
            "id": 2,
            "title": "Admission failures",
            "kind": "timeseries",
            "queries": [
              {
                "ref": "A",
                "legend": "{{reason}}",
                "expression": "sum by (reason) (rate(fulfillment_admission_failures_total{environment='$environment'}[5m]))"
              }
            ],
            "unit": "ops/s",
            "stack": "normal"
          },
          {
            "id": 3,
            "title": "Oldest unshipped order",
            "kind": "gauge",
            "query": "max(fulfillment_oldest_unshipped_seconds{environment='$environment',facility=~'$facility'})",
            "unit": "seconds",
            "min": 0,
            "max": 14400
          }
        ]
      },
      {
        "title": "Workflow health",
