              },
              {
                "ref": "B",
                "legend": "pack p95",
                "expression": "histogram_quantile(0.95, sum by (le) (rate(pack_duration_seconds_bucket{environment='$environment'}[10m])))"
              }
            ],
            "unit": "seconds"
          },
          {
            "id": 5,
            "title": "Worker leases",
            "kind": "timeseries",
            "queries": [
              {
                "ref": "A",
                "legend": "active",
                "expression": "sum(worker_leases{state='active',facility=~'$facility'})"
              },
              {
                "ref": "B",
                "legend": "waiting",
                "expression": "sum(worker_leases{state='waiting',facility=~'$facility'})"
              }
            ],
            "unit": "short"
          },
          {
            "id": 6,
            "title": "Carrier handoff errors",
            "kind": "table",
            "query": "topk(10, sum by (carrier,error_code) (increase(carrier_handoff_failures_total{environment='$environment'}[1h])))",
            "columns": [
              { "field": "carrier", "label": "Carrier" },
              { "field": "error_code", "label": "Code" },
              { "field": "value", "label": "Failures", "align": "right" }
            ]
          }
        ]
      }
    ],
